<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource, toast } from 'frappe-ui'
import { useListPersistence } from '../composables/useListPersistence'

const router = useRouter()
const listPersistence = useListPersistence('ToDoList')
function goBack() {
	router.push({ name: 'Home' })
}
function goCreate() {
	router.push({ name: 'CreateToDo' })
}
function goDetail(item) {
	router.push({ name: 'ToDoDetail', params: { name: item.name } })
}
function goMessages(item) {
	router.push({ name: 'ToDoDetail', params: { name: item.name }, query: { tab: 'messages' } })
}

const TABS = [
	{ key: 'open', label: 'Open' },
	{ key: 'closed', label: 'Closed' },
]
const tab = ref('open')

const res = createResource({
	url: 'juragan.api.portal.todo.get_todos',
	method: 'GET',
	auto: true,
	makeParams: () => ({ tab: tab.value }),
})
const loading = computed(() => res.loading)

function selectTab(k) {
	if (tab.value === k) return
	tab.value = k
	res.reload()
}

// ===== Filter (Priority & Status) =====
const PRIORITY_OPTIONS = ['High', 'Medium', 'Low']
const STATUS_OPTIONS = ['Open', 'Closed', 'Cancelled']

const showFilter = ref(false)
const showPriorityPick = ref(false)
const showStatusPick = ref(false)
const dPriority = ref('') // draft (di dalam sheet)
const dStatus = ref('')
const aPriority = ref('') // applied (dipakai memfilter)
const aStatus = ref('')

const hasActiveFilter = computed(() => !!aPriority.value || !!aStatus.value)

function openFilter() {
	dPriority.value = aPriority.value
	dStatus.value = aStatus.value
	showFilter.value = true
}
function pickFilterPriority(p) {
	dPriority.value = dPriority.value === p ? '' : p // tap lagi = batal pilih
	showPriorityPick.value = false
}
function pickFilterStatus(s) {
	dStatus.value = dStatus.value === s ? '' : s
	showStatusPick.value = false
}

// ===== Update Status per card =====
const showStatusUpdate = ref(false)
const statusEditItem = ref(null)
const updatingStatus = ref(false)
const updateStatusRes = createResource({
	url: 'juragan.api.portal.todo.update_todo_status',
	method: 'POST',
})

function openStatusUpdate(item) {
	statusEditItem.value = item
	showStatusUpdate.value = true
}
async function updateStatus(status) {
	const item = statusEditItem.value
	if (!item || updatingStatus.value) return
	if (item.status === status) {
		showStatusUpdate.value = false
		return
	}
	updatingStatus.value = true
	try {
		await updateStatusRes.submit({ name: item.name, status })
		toast.success(`Status diubah ke ${status}.`)
		showStatusUpdate.value = false
		res.reload()
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal mengubah status.')
	} finally {
		updatingStatus.value = false
	}
}
function applyFilter() {
	aPriority.value = dPriority.value
	aStatus.value = dStatus.value
	listPersistence.writeSession({ filters: { priority: aPriority.value, status: aStatus.value } })
	showFilter.value = false
}
function clearFilter() {
	dPriority.value = ''
	dStatus.value = ''
	aPriority.value = ''
	aStatus.value = ''
	listPersistence.clearSession()
	showFilter.value = false
}

const savedFilters = listPersistence.readSession({
	filters: { priority: '', status: '' },
}).filters
aPriority.value = PRIORITY_OPTIONS.includes(savedFilters.priority) ? savedFilters.priority : ''
aStatus.value = STATUS_OPTIONS.includes(savedFilters.status) ? savedFilters.status : ''

const items = computed(() => {
	let list = res.data || []
	if (aPriority.value) list = list.filter((i) => i.priority === aPriority.value)
	if (aStatus.value) list = list.filter((i) => i.status === aStatus.value)
	return list
})

// ===== Tampilan =====
function plainText(html) {
	if (!html) return ''
	return String(html)
		.replace(/<[^>]*>/g, ' ')
		.replace(/&nbsp;/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
}

const PRIORITY_PILL = {
	High: 'border-ui-line-red-200 text-ui-ink-red-500',
	Medium: 'border-ui-line-amber-200 text-ui-ink-amber-500',
	Low: 'border-ui-line-blue-200 text-ui-ink-blue-500',
}
const PRIORITY_DOT = {
	High: 'bg-red-500',
	Medium: 'bg-ui-surface-amber-400',
	Low: 'bg-blue-500',
}
function priorityPillClass(p) {
	return PRIORITY_PILL[p] || PRIORITY_PILL.Low
}
function priorityDotClass(p) {
	return PRIORITY_DOT[p] || PRIORITY_DOT.Low
}

const MONTHS_ABBR = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'May',
	'Jun',
	'Jul',
	'Aug',
	'Sep',
	'Oct',
	'Nov',
	'Dec',
]
function formatDate(v) {
	if (!v) return '—'
	const [y, m, d] = String(v).split('-').map(Number)
	if (!y || !m || !d) return String(v)
	return `${d} ${MONTHS_ABBR[m - 1]} ${y}`
}

function initials(name) {
	const parts = String(name || '')
		.trim()
		.split(/\s+/)
		.filter(Boolean)
	if (!parts.length) return '?'
	if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
	return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
}
</script>
